my_actions = []

def evaluate(current_reputation, observation, my_history, round_num):
    # Exponential moving average to keep reputation in [-1, 1]
    alpha = 0.8  # weight on current reputation
    inc = 0.2    # adjustment per observation
    if observation['action'] == 'cooperate':
        new_rep = alpha * current_reputation + inc
    else:
        new_rep = alpha * current_reputation - inc
    # Clamp to [-1, 1] to satisfy return requirement
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    global my_actions
    # Compute personal cooperation rate from my own history
    if len(my_actions) == 0:
        coop_rate = 0.5
    else:
        coop_rate = sum(my_actions) / len(my_actions)
    # Decision rule: cooperate if recipient's reputation is high enough and I've been cooperative
    if recipient_reputation > 0.3 and coop_rate > 0.3:
        decision = True   # cooperate
    else:
        decision = False  # defect
    # Record my action for future decisions
    my_actions.append(decision)
    return decision
